3365abeefff235850ee24b766a9194ad7d034331f6"},["Conditions/common.lua"]={["bindings"]={["SpellData"]={["kind"]="value"},["Widget_GetSpellId"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"},{["description"]="Stored spell ID to resolve.",["name"]="spellid",["type"]="number"},{["description"]="True to require this exact rank; false or nil follows the available rank.",["name"]="ranked",["type"]="boolean | nil"}},["bindings"]={["SpellData"]="builtin:Conditions/common.lua:SpellData"},["callName"]="addon:Widget_GetSpellId",["code"]="\010    if (WOW_PROJECT_ID ~= WOW_PROJECT_MAINLINE) then\010        if not ranked then\010            local resolved, reason = SpellData:GetSpellId(spellid)\010            return resolved, reason or (not resolved and \"spell-data-unavailable\" or nil)\010        end\010    end\010    return spellid\010",["description"]="Resolve the spell identifier stored by a condition. With exact rank enabled the supplied ID is retained; otherwise ranked Classic clients resolve the currently known rank through the spell catalog. Returns nil and an availability reason if resolution cannot be completed.",["kind"]="function",["line"]=15,["parameters"]={"self","spellid","ranked"},["returns"]={{["description"]="Resolved spell ID, or nil when unavailable.",["type"]="number | nil"},{["description"]="Availability reason when resolution fails; nil on success.",["type"]="string | nil"}}},["Widget_SpellWidget"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"},{["description"]="Specialization scope used to resolve spell suggestions.",["name"]="spec",["type"]="number"},{["description"]="Reference input kind, such as Spec_EditBox, used for spell suggestions.",["name"]="editbox",["type"]="string"},{["description"]="Condition value record containing spell, ranked and disabled fields; updated in place.",["name"]="value",["type"]="table"},{["description"]="Resolver mapping a typed spell name to its ID.",["name"]="nametoid",["type"]="function"},{["description"]="Predicate that validates the proposed spell value.",["name"]="isvalid",["type"]="function"},{["description"]="Callback receiving the committed spell value.",["name"]="update",["type"]="function"}},["bindings"]={["SpellData"]="builtin:Conditions/common.lua:SpellData"},["callName"]="addon:Widget_SpellWidget",["code"]="\010    local spell_group = addon:CreateConditionGroup()\010    spell_group:SetLayout('RM-SpellField')\010    local rankChoice\010\010    local spell = addon:CreateSpellEditBox(editbox,value.spell)\010    local initialSpell=type(value.spell)==\"string\" and SpellData:GetSpellId(value.spell) or value.spell\010    local spellIcon = addon:CreateSpellActionIcon(spec == BOOKTYPE_PET and \"pet\" or \"spell\",initialSpell,isvalid)\010    spellIcon:SetWidth(44)\010    spellIcon:SetHeight(44)\010    spellIcon:SetText(value.spell)\010    spellIcon:SetCallback(\"OnEnterPressed\", function(_, _, v)\010        v = tonumber(v)\010        if v and isvalid(v) then\010            value.spell = v\010            spellIcon:SetText(v)\010            spell:SetText(SpellData:SpellName(value.spell, not value.ranked))\010            if GameTooltip:IsOwned(spellIcon.frame) and GameTooltip:IsVisible() then\010                GameTooltip:SetHyperlink(\"spell:\" .. v)\010            end\010        else\010            value.spell = nil\010            spellIcon:SetText(nil)\010            spell:SetText(nil)\010            if GameTooltip:IsOwned(spellIcon.frame) and GameTooltip:IsVisible() then\010                GameTooltip:Hide()\010            end\010        end\010        update()\010    end)\010    spellIcon:SetCallback(\"OnEnter\", function()\010        if value.spell then\010            GameTooltip:SetOwner(spellIcon.frame, \"ANCHOR_BOTTOMRIGHT\", 3)\010            GameTooltip:SetHyperlink(\"spell:\" .. value.spell)\010        end\010    end)\010    spellIcon:SetCallback(\"OnLeave\", function()\010        if GameTooltip:IsOwned(spellIcon.frame) then\010            GameTooltip:Hide()\010        end\010    end)\010    spellIcon:SetDisabled(value.disabled)\010    spell_group:AddChild(spellIcon)\010\010    if WOW_PROJECT_ID ~= WOW_PROJECT_MAINLINE and spec ~= BOOKTYPE_PET then\010        local nr_button = addon:CreateConditionCheckBox()\010        nr_button:SetLabel(L[\"Use this exact spell rank\"])\010        nr_button:SetValue(value.ranked or false)\010        nr_button:SetCallback(\"OnValueChanged\", function(_, _, val)\010            value.ranked = val\010            spell:SetUserData(\"norank\", not val)\010            spell:SetText(value.spell and SpellData:SpellName(value.spell, not value.ranked))\010            update()\010        end)\010        nr_button:SetDisabled(value.disabled)\010        rankChoice=nr_button\010    end\010\010    spell:SetFullWidth(true)\010    spell:SetLabel('')\010    spell:SetText(value.spell and SpellData:SpellName(value.spell, not value.ranked))\010    spell:SetUserData(\"norank\", not value.ranked)\010    spell:SetUserData(\"spec\", spec)\010    spell:SetCallback(\"OnEnterPressed\", function(_, _, v)\010        if not addon.isint(v) then\010            v = nametoid(v)\010        else\010            v = tonumber(v)\010        end\010        if isvalid(v) then\010            value.spell = v\010            spell:SetText(SpellData:SpellName(value.spell, not value.ranked))\010        else\010            value.spell = nil\010            spell:SetText(nil)\010        end\010        spellIcon:SetText(value.spell)\010        update()\010    end)\010    spell:SetDisabled(value.disabled)\010    spell_group:AddChild(spell)\010    if rankChoice then\010        rankChoice.frame.GetFontString=function() return rankChoice.button:GetFontString() end\010        spell_group:AddChild(rankChoice)\010    end\010\010    return spell_group\010",["description"]="Create a spell input with suggestions, validation and spell-link support for custom condition widgets. The update callback owns saving a chosen value; add the returned widget to the callback parent.",["kind"]="function",["line"]=41,["parameters"]={"self","spec","editbox","value","nametoid","isvalid","update"},["returns"]={{["description"]="Spell field group containing an action icon, reference input and optional rank control.",["type"]="AceGUIContainer"}}},["Widget_UnitWidget"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"},{["description"]="Condition value record updated when a unit is chosen.",["name"]="value",["type"]="table"},{["description"]="Unit key-to-display-name map shown in the selector.",["name"]="units",["type"]="table"},{["description"]="Callback invoked after changing the selected unit.",["name"]="update",["type"]="function"},{["description"]="Value record field to edit; defaults to unit.",["name"]="field",["type"]="string | nil"}},["bindings"]={},["callName"]="addon:Widget_UnitWidget",["code"]="\010    if field == nil then\010        field = \"unit\"\010    end\010    local unit = addon:CreateConditionDropdown()\010    unit:SetLabel(L[\"Unit\"])\010    unit:SetCallback(\"OnValueChanged\", function(_, _, v)\010        value[field] = v\010        update()\010    end)\010    unit:SetDisabled(value.disabled)\010    unit.configure = function()\010        unit:SetList(units, addon.keys(units))\010        unit:SetValue(value[field])\010    end\010\010    return unit\010",["description"]="Create a configured unit selector bound to a condition value record. Returns the widget for the caller to add to the condition callback parent.",["kind"]="function",["line"]=487,["parameters"]={"self","value","units","update","field"},["returns"]={{["description"]="Configured unit selector; add it with parent:AddChild(widget).",["type"]="RMConditionSelector"}}}},["hash"]="c06196a707794739fcee7ec850c11c1f8901b5ee05bb6fe51ded7f8e39e1898d"},["Conditions/debuffs.lua"]={["bindings"]={["color"]={["kind"]="value"},["helpers"]={["kind"]="value"}},["hash"]="14587515cc79c704356364a6617972d8c0f3fd519d0a6446f16785a1c5121740"},["Conditions/ext_stats.lua"]={["bindings"]={["color"]={["kind"]="value"},["ecs_state"]={["kind"]="value"},["helpers"]={["kind"]="value"}},["hash"]="09e4bb92855b415ed5c1c4a74b4517ceeefcfeba5271b56e241ba2965f87fbc9"},["Conditions/item.lua"]={["bindings"]={["color"]={["kind"]="value"},["get_item_desc"]={["bindings"]={["color"]="builtin:Conditions/item.lua:color"},["code"]="\010    if not addon:IsConditionItemReference(items) then return nil end\010    local itemsets = addon.db.profile.itemsets\010    local global_itemsets = addon.db.global.itemsets\010    if itemsets~=nil and type(itemsets)~='table' or global_itemsets~=nil and type(global_itemsets)~='table' then return nil end\010\010    if type(items) == \"string\" then\010        local set=(itemsets or {})[items];local tint=color.WHITE\010        if set==nil then set=(global_itemsets or {})[items];tint=color.CYAN end\010        if type(set)=='table' and type(set.name)=='string' then return string.format(L[\"a %s item set item\"],tint..set.name..color.RESET) end\010    elseif items and #items > 0 then\010        local info=addon.Platform:GetItemMetadata(items[1])\010        local link=info and (info.link or info.name) or items[1]\010        if #items > 1 then\010            return string.format(L[\"%s or %d others\"], link, #items-1)\010        else\010            return link\010        end\010    end\010    return nil\010",["kind"]="function",["line"]=13,["parameters"]={"items"}},["helpers"]={["kind"]="value"},["itemHelp"]={["bindings"]={["helpers"]="builtin:Conditions/item.lua:helpers"},["code"]="\010    addon.layout_condition_itemwidget_help(frame)\010    frame:AddChild(helpers.Gap())\010    frame:AddChild(helpers.CreateText(L[\"Item sets are checked in priority order. Bag counts use the first carried candidate, not the sum. A