ues[index])\010            else value=math.max(value,values[index]) end\010        end\010        return value\010    end\010    return nil,\"invalid-operation\"\010",["kind"]="function",["line"]=7,["parameters"]={"values","operation"}},["color"]={["kind"]="value"},["helpers"]={["kind"]="value"}},["hash"]="5f7e4e614e1be98418074c2fafb838cd8b4833b6ac7d57b3c960025bbcda4ffc"},["Conditions/spell.lua"]={["bindings"]={["color"]={["kind"]="value"},["helpers"]={["kind"]="value"}},["hash"]="c688ef2fdfe8346f3c8ca3c426e88fe95ff82124b8cb5cb24c12ef16723a0f0d"},["Conditions/stats.lua"]={["bindings"]={["color"]={["kind"]="value"},["helpers"]={["kind"]="value"}},["hash"]="dc77dce5ded0838f330c9e5bbd735b541eeec25896260dfe6cd7dc47a2f1edb8"},["Conditions/talent.lua"]={["bindings"]={["AceGUI"]={["kind"]="value"},["dropdown"]={["bindings"]={},["code"]="\010    local widget=addon:CreateConditionDropdown();widget:SetFullWidth(true);widget:SetLabel(title)\010    widget:SetCallback(\"OnValueChanged\",function(_,_,value) changed(value) end);parent:AddChild(widget)\010    return widget\010",["kind"]="function",["line"]=24,["parameters"]={"parent","title","changed"}},["gridWidget"]={["bindings"]={["dropdown"]="builtin:Conditions/talent.lua:dropdown",["group"]="builtin:Conditions/talent.lua:group",["icon"]="builtin:Conditions/talent.lua:icon",["info"]="builtin:Conditions/talent.lua:info",["platform"]="builtin:Conditions/talent.lua:platform",["text"]="builtin:Conditions/talent.lua:text"},["code"]="\010    local choices,order={},{}\010    for index=1,18 do\010        local talent=platform:GetGridTalentInfo(index,group(spec))\010        if talent then choices[index]=talent.name;order[#order+1]=index end\010    end\010    if value.layout~=\"grid\" and (value.tree~=nil or value.value~=nil) then\010        text(parent,L[\"This reference belongs to another talent layout. Selecting a talent explicitly replaces it; viewing does not convert it.\"])\010    end\010    local talentIcon=icon(parent,value,spec)\010    local picker\010    picker=dropdown(parent,L[\"Talent\"],function(selected)\010        value.layout,value.value=\"grid\",selected\010        value.tree,value.talent,value.operator=nil,nil,nil\010        local talent=info(value,spec);talentIcon:SetImage(talent and talent.icon);update()\010    end)\010    picker:SetDisabled(#order==0)\010    picker.configure=function() picker:SetList(choices,order);picker:SetValue(value.layout==\"grid\" and value.value or nil) end\010",["kind"]="function",["line"]=80,["parameters"]={"parent","spec","value","update"}},["group"]={["bindings"]={["integer"]="builtin:Conditions/talent.lua:integer",["platform"]="builtin:Conditions/talent.lua:platform"},["code"]="\010    if platform:GetClientInfo().family==\"progression\" and integer(spec,1,4) then return spec end\010",["kind"]="function",["line"]=14,["parameters"]={"spec"}},["icon"]={["bindings"]={["AceGUI"]="builtin:Conditions/talent.lua:AceGUI",["info"]="builtin:Conditions/talent.lua:info"},["code"]="\010    local widget=AceGUI:Create(\"Icon\");widget:SetWidth(44);widget:SetHeight(44);widget:SetImageSize(36,36)\010    local current=info(value,spec);widget:SetImage(current and current.icon)\010    widget:SetCallback(\"OnEnter\",function()\010        local observed=info(value,spec)\010        if observed then\010            GameTooltip:SetOwner(widget.frame,\"ANCHOR_BOTTOMRIGHT\",3)\010            if observed.spellID then GameTooltip:SetHyperlink(\"spell:\"..observed.spellID)\010            else GameTooltip:SetText(observed.name) end\010        end\010    end)\010    widget:SetCallback(\"OnLeave\",function() if GameTooltip:IsOwned(widget.frame) then GameTooltip:Hide() end end)\010    parent:AddChild(widget)\010    return widget\010",["kind"]="function",["line"]=29,["parameters"]={"parent","value","spec"}},["info"]={["bindings"]={["group"]="builtin:Conditions/talent.lua:group",["platform"]="builtin:Conditions/talent.lua:platform",["treeShape"]="builtin:Conditions/talent.lua:treeShape"},["code"]="\010    if value.layout==\"grid\" then return platform:GetGridTalentInfo(value.value,group(spec)) end\010    if treeShape(value) then return platform:GetTreeTalentInfo(value.tree,value.talent,group(spec)) end\010",["kind"]="function",["line"]=17,["parameters"]={"value","spec"}},["integer"]={["bindings"]={},["code"]="\010    return type(value)==\"number\" and value>=minimum and value<=maximum and value%1==0\010",["kind"]="function",["line"]=5,["parameters"]={"value","minimum","maximum"}},["legacySlot"]={["bindings"]={["integer"]="builtin:Conditions/talent.lua:integer"},["code"]="\010    return value.layout==nil and value.tree==nil and value.talent==nil and integer(value.value,1,21)\010",["kind"]="function",["line"]=11,["parameters"]={"value"}},["platform"]={["kind"]="value"},["text"]={["bindings"]={["AceGUI"]="builtin:Conditions/talent.lua:AceGUI"},["code"]="\010    local label=AceGUI:Create(\"Label\");label:SetFullWidth(true);label:SetText(message);parent:AddChild(label)\010",["kind"]="function",["line"]=21,["parameters"]={"parent","message"}},["treeExists"]={["bindings"]={["platform"]="builtin:Conditions/talent.lua:platform"},["code"]="\010    local count,reason=addon.getCached(cache,platform.GetTalentTreeCount,platform)\010    if count==nil then return nil,reason end\010    if value.tree>count then return nil,'talent-tree-unavailable' end\010    return true\010",["kind"]="function",["line"]=156,["parameters"]={"value","cache"}},["treeName"]={["bindings"]={["group"]="builtin:Conditions/talent.lua:group",["integer"]="builtin:Conditions/talent.lua:integer",["platform"]="builtin:Conditions/talent.lua:platform"},["code"]="\010    local tree=integer(value.tree,1,16) and platform:GetTalentTreeInfo(value.tree,group(spec))\010    return tree and tree.name or value.tree and string.format(L['Talent tree %s'],tostring(value.tree)) or L['<talent tree>']\010",["kind"]="function",["line"]=143,["parameters"]={"value","spec"}},["treePicker"]={["bindings"]={["dropdown"]="builtin:Conditions/talent.lua:dropdown",["group"]="builtin:Conditions/talent.lua:group",["platform"]="builtin:Conditions/talent.lua:platform",["text"]="builtin:Conditions/talent.lua:text"},["code"]="\010    local choices,order={},{}\010    local count=platform:GetTalentTreeCount()\010    for index=1,count or 0 do local tree=platform:GetTalentTreeInfo(index,group(spec));if tree then choices[index]=tree.name;order[#order+1]=index end end\010    if not count then text(parent,L['This client does not expose a Classic talent-tree layout. The saved tree reference is preserved.']) end\010    local picker=dropdown(parent,L['Talent tree'],function(selected) value.tree=selected;update() end)\010    picker:SetDisabled(#order==0 or value.disabled==true)\010    picker.configure=function() picker:SetList(choices,order);picker:SetValue(value.tree) end\010",["kind"]="function",["line"]=147,["parameters"]={"parent","spec","value","update"}},["treeShape"]={["bindings"]={},["code"]="\010    return (value.layout==nil or value.layout==\"tree\") and value.tree~=nil and value.talent~=nil\010",["kind"]="function",["line"]=8,["parameters"]={"value"}},["treeWidget"]={["bindings"]={["dropdown"]="builtin:Conditions/talent.lua:dropdown",["group"]="builtin:Conditions/talent.lua:group",["icon"]="builtin:Conditions/talent.lua:icon",["info"]="builtin:Conditions/talent.lua:info",["platform"]="builtin:Conditions/talent.lua:platform"},["code"]="\010    local trees,treeOrder={},{}\010    for index=1,platform:GetTalentTreeCount() or 0 do\010        local tree=platform:GetTalentTreeInfo(index,group(spec))\010        if tree then trees[index]=tree.name;treeOrder[#treeOrder+1]=index end\010    end\010    local talents,talentOrder={},{}\010    local talentIcon,talentPicker,treePicker\010    local function choices()\010        talents,talentOrder={},{}\010        if value.tree then\010            for index=1,platform:GetTreeTalentCount(value.tree) or 0 do\010                local talent=platform:GetTreeTalentInfo(value.tree,index,group(spec))\010                if talent then talents[index]=talent.name;talentOrder[#talentOrder+1]=index end\010            end\010        end\010    end\010    choices()\010    treePicker=dropdown(parent,L[\"Talent Tree\"],function(selected)\010        if selected==value.tree then return end\010        local wasTree=value.layout==\"tree\" or value.layout==nil and value.tree~=nil\010        value.tree,value.talent,value.layout=selected,nil,\"tree\"\010        if not wasTree then value.value,value.operator=nil,nil end\010        choices();talentPicker:SetList(talents,talentOrder);talentPicker:SetValue(nil)\010        talentPicker:SetDisabled(#talentOrder==0);talentIcon:SetImage(\"Interface\\\\Icons\\\\INV_Misc_QuestionMark\");update()\010    end)\010    treePicker.configure=function() treePicker:SetList(trees,treeOrder);treePicker:SetValue(value.tree) end\010    talentIcon=icon(parent,value,spec)\010    talentPicker=dropdown(parent,L[\"Talent\"],function(selected)\010        value.talent,value.layout=selected,\"tree\"\010        local talent=info(value,spec);talentIcon:SetImage(talent and talent.icon);update()\010    end)\010    talentPicker:SetDisabled(#talentOrder==0)\010    talentPicker.configure=function() talentPicker:SetList(talents,talentOrder);talentPicker:SetValue(value.talent) end\010    parent:AddChild(addon:Widget_OperatorWidget(value,L[\"Points\"],update))\010",["kind"]="function",["line"]=44,["parameters"]={"parent","spec","value","update"}}},["hash"]="b0f3d99dfdcfdf8146af344c8e7a0709ee4c80e548cdff7f2dc5b9a0297b7331"},["Conditions/totem.lua"]={["bindings"]={["amount"]={["bindings"]={},["code"]="\010    return type(value.value)==\"number\" and value.value==value.value and value.value>=0 and value.value<math.huge\010        and type(value.operator)==\"string\" and addon.isin(addon.operators,value.operator)\010",["kind"]="function",["line"]=21,["parameters"]={"value"}},["color"]={["kind"]="value"},["element"]={["bindings"]={},["code"]="\010    return addon.IsConditionSpellID(value.spell) and value.spell<=4\010",["kind"]="function",["line"]=18,["parameters"]={"value"}},["findSpecific"]={["bindings"]={["observe"]="builtin:Conditions/totem.lua:observe",["platform"]="builtin:Conditions/totem.lua:platform",["remaining"]="builtin:Conditions/totem.lua:remaining"},["code"]="\010    local target,reason=observe(cache,platform.GetSpellInfo,value.spell)\010    if not target then return nil,reason end\010    local count,why=observe(cache,platform.GetTotemSlotCount)\010    if not count then return nil,why end\010    local unavailable\010    for slot=1,count do\010        local record,problem=observe(cache,platform.GetTotemInfo,slot)\010        if not record then unavailable=unavailable or problem or \"totem-data-unavailable\"\010        elseif record.active and remaining(record,start)>0 then\010            local matches=false\010            if value.ranked then\010                if record.spellID then matches=record.spellID==value.spell\010                elseif record.name==target.name or record.name==\"\" then unavailable=unavailable or \"totem-rank-unavailable\" end\010            else\010                matches=record.spellID==value.spell or record.name==target.name\010                if not matches and record.name==\"\" then\010                    local info,issue\010                    if record.spellID then info,issue=observe(cache,platform.GetSpellInfo,record.spellID) end\010                    if info then matches=info.name==target.name\010                    else unavailable=unavailable or issue or \"totem-identity-unavailable\" end\010                end\010            end\010            if matches and (not compareTime or addon.compare(value.operator,addon.round(remaining(record,start),3),value.value)) then return true end\010        end\010    end\010    if unavailable then return nil,unavailable end\010    return false\010",["kind"]="function",["line"]=28,["parameters"]={"value","cache","start","compareTime"}},["helpers"]={["kind"]="value"},["observe"]={["bindings"]={["platform"]="builtin:Conditions/totem.lua:platform"},["code"]="\010    return addon.getCached(cache,method,platform,...)\010",["kind"]="function",["line"]=11,["parameters"]={"cache","method","..."}},["platform"]={["kind"]="value"},["remaining"]={["bindings"]={},["code"]="\010    if not record.active then return 0 end\010    return math.max(0,record.startTime+record.duration-(start or GetTime()))\010",["kind"]="function",["line"]=14,["parameters"]={"record","start"}},["specific"]={["bindings"]={},["code"]="\010    return addon.IsConditionSpellID(value.spell) and (value.ranked==nil or type(value.ranked)==\"boolean\")\010",["kind"]="function",["line"]=25,["parameters"]={"value"}}},["hash"]="63fed326f44268b2fe7877c3b0c2ad84d43b0198a62239fc208352dd00fa12fa"},["Conditions/weapon.lua"]={["bindings"]={["color"]={["kind"]="value"},["enchantObservation"]={["bindings"]={},["code"]="\010    if type(GetWeaponEnchantInfo)~=\"function\" then return nil,nil,nil,\"missing-api\" end\010    -- The protected cached API returns both hands' original tuple unchanged.\010    ---@diagnostic disable-next-line: unbalanced-assignments\010    local ok, main, mainExpires, mainCharges, _, off, offExpires, offCharges = pcall(addon.getCached, cache, GetWeaponEnchantInfo)\010    if not ok then return nil,nil,nil,\"api-error\" end\010    local enchanted, expires, charges=main,mainExpires,mainCharges\010    if value.offhand then enchanted,expires,charges=off,offExpires,offCharges end\010    if not addon.Platform:CanReadValue(enchanted) then return nil,nil,nil,\"restricted-value\" end\010    if enchanted==nil or enchanted==false or enchanted==0 then return false end\010    if enchanted~=true and enchanted~=1 then return nil,nil,nil,\"invalid-weapon-observation\" end\010    return true,expires,charges\010",["kind"]="function",["line"]=9,["parameters"]={"value","cache"}},["helpers"]={["kind"]="value"},["numericObservation"]={["bindings"]={},["code"]="\010    if not addon.Platform:CanReadValue(value) then return nil,\"restricted-value\" end\010    if type(value)~=\"number\" or value~=value or value<0 or value==math.huge then return nil,\"invalid-weapon-observation\" end\010    return value\010",["kind"]="function",["line"]=22,["parameters"]={"value"}},["swingSpeed"]={["bindings"]={["numericObservation"]="builtin:Conditions/weapon.lua:numericObservation"},["code"]="\010    if type(UnitAttackSpeed)~=\"function\" then return nil,\"missing-api\" end\010    -- pcall forwards the mainhand and offhand speeds from the observation.\010    ---@diagnostic disable-next-line: unbalanced-assignments\010    local ok,main,off=pcall(addon.getCached,cache,UnitAttackSpeed,\"player\")\010    if not ok then return nil,\"api-error\" end\010    local speed=main;if value.offhand then speed=off end\010    return numericObservation(speed)\010",["kind"]="function",["line"]=27,["parameters"]={"value","cache"}}},["hash"]="91b01a6795e1e18c41decc584dd47f8adc57d976325a016b97a231d4745638b7"},["Platform/actions.lua"]={["bindings"]={["Platform_GetSpellRangeState"]={["args"]={{["description"]="Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.",["name"]="self",["type"]="RMPlatform"},{["description"]="Spell ID whose range should be checked.",["name"]="id",["type"]="number"},{["description"]="Unit token, such as target; nil uses target.",["name"]="unit",["type"]="string | nil"},{["description"]="Spell-book scope: spell, pet or any.",["name"]="bank",["type"]="string"}},["bindings"]={["call"]="builtin:Platform/actions.lua:call",["findSlot"]="builtin:Platform/actions.lua:findSlot",["spellID"]="builtin:Platform/actions.lua:spellID"},["callName"]="addon.Platform:GetSpellRangeState",["code"]="\010    local valid,reason=spellID(id)\010    if not valid then return nil,reason end\010    if not self:CanReadValue(unit) or not self:CanReadValue(bank) then return nil,\"restricted-value\" end\010    if unit~=nil and (type(unit)~=\"string\" or unit==\"\") then return nil,\"invalid-unit\" end\010    if bank~=\"spell\" and bank~=\"pet\" and bank~=\"any\" then return nil,\"invalid-spell-bank\" end\010    unit=unit or \"target\"\010    local nativeRange=C_Spell and C_Spell.IsSpellInRange\010    local nativeShape=C_Spell and C_Spell.SpellHasRange\010    local slot,book,slotReason\010    local function legacySlot()\010        if not slot then slot,book,slotReason=findSlot(id,bank) end\010        return slot,slotReason\010    end\010    local hasRange,why,queriedShape\010    if type(nativeShape)==\"function\" then\010        queriedShape=true\010        hasRange,why=call(nativeShape,id)\010    elseif type(nativeRange)~=\"function\" and type(SpellHasRange)==\"function\" then\010        if not legacySlot() then return nil,slotReason end\010        queriedShape=true\010        hasRange,why=call(SpellHasRange,slot,book)\010    end\010    if why then return nil,why end\010    if hasRange~=nil then\010        if type(hasRange)~=\"boolean\" then return nil,\"invalid-api-result\" end\010        if not hasRange then return {applicable=false} end\010    elseif queriedShape then return nil,\"invalid-api-result\" end\010    local inRange\010    if type(nativeRange)==\"function\" then\010        inRange,why=call(nativeRange,id,unit)\010        if why then return nil,why end\010        if inRange~=nil and type(inRange)~=\"boolean\" then return nil,\"invalid-api-result\" end\010    else\010        if type(IsSpellInRange)~=\"function\" then return nil,\"missing-api\" end\010        if not legacySlot() then return nil,slotReason end\010        inRange,why=call(IsSpellInRange,slot,book,unit)\010        if why then return nil,why end\010        if inRange==0 then inRange=false elseif inRange==1 then inRange=true end\010        if inRange~=nil and type(inRange)~=\"boolean\" then return nil,\"invalid-api-result\" end\010    end\010    if inRange==nil then return nil,\"invalid-range-check\" end\010    return {applicable=true,inRange=inRange}\010",["description"]="Read spell-specific range for a unit using the appropriate client API or spell-book slot. A spell without a range restriction returns applicable=false; otherwise applicable=true and inRange records whether the unit is in range. Unknown or inaccessible observations return nil with a reason.",["kind"]="function",["line"]=40,["parameters"]={"self","id","unit","bank"},["returns"]={{["description"]="Range record with applicable and, when applicable, inRange; nil when unavailable.",["type"]="table | nil"},{["description"]="Availability or validation reason when the record is nil.",["type"]="string | nil"}}},["call"]={["bindings"]={["platform"]="builtin:Platform/actions.lua:platform"},["code"]="\010    if type(fn)~=\"function\" then return nil,\"missing-api\" end\010    local ok,value=pcall(fn,...)\010    if not ok then return nil,\"api-error\" end\010    if not platform:CanReadValue(value) then return nil,\"restricted-value\" end\010    return value\010",["kind"]="function",["line"]=9,["parameters"]={"fn","..."}},["findSlot"]={["bindings"]={["call"]="builtin:Platform/actions.lua:call"},["code"]="\010    local pet=bank==\"pet\"\010    local slot,reason=call(FindSpellBookSlotBySpellID,id,pet)\010    if reason then return nil,nil,reason end\010    if slot==nil and bank==\"any\" then\010        pet=true;slot,reason=call(FindSpellBookSlotBySpellID,id,true)\010        if reason then return nil,nil,reason end\010    end\010    if slot==nil then return nil,nil,\"spell-not-in-book\" end\010    if type(slot)~=\"number\" or slot<1 or slot==math.huge or slot%1~=0 then return nil,nil,\"invalid-api-result\" end\010    return slot,pet and (BOOKTYPE_PET or \"pet\") or (BOOKTYPE_SPELL or \"spell\")\010",["kind"]="function",["line"]=28,["parameters"]={"id","bank"}},["platform"]={["kind"]="value"},["spellID"]={["bindings"]={["platform"]="builtin:Platform/actions.lua:platform"},["code"]="\010    if not platform:CanReadValue(id) then return nil,\"restricted-value\" end\010    if type(id)~=\"number\" or id<1 or id==math.huge or id%1~=0 then return nil,\"invalid-spell\" end\010    return true\010",["kind"]="function",["line"]=4,["parameters"]={"id"}}},["hash"]="c540aab94ba6e7907539aee2a43bd4b3008fe7b7de63cf8d4a727af80e3732a2"},["Platform/spells.lua"]={["bindings"]={["Platform_GetSpellCharges"]={["args"]={{["description"]="Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.",["name"]="self",["type"]="RMPlatform"},{["description"]="Spell ID or client-recognized spell name whose charges should be read.",["name"]="spell",["type"]="number | string"}},["bindings"]={["copy"]="builtin:Platform/spells.lua:copy",["identifier"]="builtin:Platform/spells.lua:identifier"},["callName"]="addon.Platform:GetSpellCharges",["code"]="\010    local valid,reason=identifier(spell)\010    if not valid then return nil,reason end\010    local ok,record\010    if C_Spell and type(C_Spell.GetSpellCharges)==\"function\" then\010        ok,record=pcall(C_Spell.GetSpellCharges,spell)\010    elseif type(GetSpellCharges)==\"function\" then\010        local current,maximum,start,duration,rate\010        ok,current,maximum,start,duration,rate=pcall(GetSpellCharges,spell)\010        if not ok then return nil,\"api-error\" end\010        record={currentCharges=current,maxCharges=maximum,cooldownStartTime=start,cooldownDuration=duration,chargeModRate=rate}\010    else return nil,\"missing-api\" end\010    if not ok then return nil,\"api-error\" end\010    if not self:CanReadValue(record) then return nil,\"restricted-value\" end\010    if record==nil then return nil,\"spell-charges-unavailable\" end\010    local charges,why=copy(record,{currentCharges=\"number\",maxCharges=\"number\",cooldownStartTime=\"number\",\010        cooldownDuration=\"number\",chargeModRate=\"number\",isActive=\"boolean\"})\010    if not charges then return nil,why end\010    if next(charges)==nil then return nil,\"spell-charges-unavailable\" end\010    local current,maximum,start,duration=charges.currentCharges,charges.maxCharges,charges.cooldownStartTime,charges.cooldownDuration\010    if current==nil or maximum==nil or start==nil or duration==nil or current<0 or current%1~=0\010        or maximum<1 or maximum%1~=0 or current>maximum or start<0 or duration<0\010        or charges.chargeModRate and charges.chargeModRate<=0 then return nil,\"invalid-api-result\" end\010    local active=current<maximum and start>0 and duration>0\010    if charges.isActive==nil then charges.isActive=active\010    elseif charges.isActive and not active then return nil,\"invalid-api-result\" end\010    charges.chargeModRate=charges.chargeModRate or 1\010    return charges\010",["description"]="Read a normalized charge record: currentCharges, maxCharges, cooldownStartTime, cooldownDuration, chargeModRate and isActive. Unsupported spells or restricted client data return nil with a reason.",["kind"]="function",["line"]=160,["parameters"]={"self","spell"},["returns"]={{["description"]="Readable charge record, or nil when unavailable.",["type"]="table | nil"},{["description"]="Availability or validation reason when the record is nil.",["type"]="string | nil"}}},["Platform_GetSpellCooldown"]={["args"]={{["description"]="Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.",["name"]="self",["type"]="RMPlatform"},{["description"]="Spell ID or client-recognized spell name whose cooldown should be read.",["name"]="spell",["type"]="number | string"}},["bindings"]={["copy"]="builtin:Platform/spells.lua:copy",["identifier"]="builtin:Platform/spells.lua:identifier"},["callName"]="addon.Platform:GetSpellCooldown",["code"]="\010    local valid, reason = identifier(spell)\010    if not valid then return nil, reason end\010    local ok, record\010    if C_Spell and type(C_Spell.GetSpellCooldown) == \"function\" then\010        ok, record = pcall(C_Spell.GetSpellCooldown, spell)\010    elseif type(GetSpellCooldown) == \"function\" then\010        local start, duration, enabled, rate\010        ok, start, duration, enabled, rate = pcall(GetSpellCooldown, spell)\010        if not ok then return nil, \"api-error\" end\010        for _, value in pairs({start=start, duration=duration, enabled=enabled, rate=rate}) do\010            if not self:CanReadValue(value) then return nil, \"restricted-value\" end\010        end\010        if start ~= nil then\010            if enabled ~= 0 and enabled ~= 1 then return nil, \"invalid-api-result\" end\010            record = {startTime=start, duration=duration, isEnabled=enabled == 1, modRate=rate or 1}\010        end\010    else return nil, \"missing-api\" end\010    if not ok then return nil, \"api-error\" end\010    if not self:CanReadValue(record) then return nil, \"restricted-value\" end\010    if record == nil then return nil, \"spell-data-unavailable\" end\010    local cooldown, why = copy(record, {startTime=\"number\", duration=\"number\", isEnabled=\"boolean\", modRate=\"number\"})\010    if not cooldown then return nil, why end\010    if cooldown.startTime == nil or cooldown.duration == nil or cooldown.isEnabled == nil\010        or cooldown.startTime < 0 or cooldown.duration < 0 or (cooldown.modRate and cooldown.modRate <= 0) then\010        return nil, \"invalid-api-result\"\010    end\010    cooldown.modRate = cooldown.modRate or 1\010    return cooldown\010",["description"]="Read and normalize a spell cooldown across supported clients. The returned record contains startTime, duration, isEnabled and modRate. The timestamps and duration already describe expiration in GetTime() seconds; do not divide them by modRate.",["kind"]="function",["line"]=87,["parameters"]={"self","spell"},["returns"]={{["description"]="Readable cooldown record, or nil when unavailable.",["type"]="table | nil"},{["description"]="Availability or validation reason when the record is nil.",["type"]="string | nil"}}},["Platform_IsSpellReady"]={["args"]={{["description"]="Rotation Master platform adapter. A dot reference requires addon.Platform as the first argument; a colon call supplies it implicitly.",["name"]="self",["type"]="RMPlatform"},{["description"]="Spell ID or client-recognized spell name whose cooldown should be checked.",["name"]="spell",["type"]="number | string"},{["description"]="Current evaluation time in seconds from GetTime(), normally evalStart.",["name"]="now",["type"]="number"}},["bindings"]={},["callName"]="addon.Platform:IsSpellReady",["code"]="\010    if not self:CanReadValue(now) then return nil, \"restricted-value\" end\010    if type(now)~=\"number\" or now~=now or now==math.huge or now==-math.huge then\010        return nil, \"invalid-time\"\010    end\010    local cooldown,reason=self:GetSpellCooldown(spell)\010    if not cooldown then return nil,reason end\010    if not cooldown.isEnabled then return false end\010    local expires=cooldown.startTime+cooldown.duration\010    if cooldown.duration==0 or expires<=now then return true end\010\010    local gcd,why=self:GetGlobalCooldown()\010    if not gcd then return nil,why end\010    if not gcd.isEnabled or gcd.duration==0 then return false end\010    -- modRate controls cooldown animation; API timestamps/duration already\010    -- describe expiration in GetTime seconds, so do not divide them by it.\010    local gcdExpires=gcd.startTime+gcd.duration\010    return gcdExpires>now and expires<=gcdExpires+0.001\010",["description"]="Check whether a spell can be recommended now, allowing a spell whose remaining cooldown ends with the current global cooldown. This checks cooldown readiness only; it does not check learned status, range or resource usability. Pass evaluation time from evalStart or GetTime().",["kind"]="function",["line"]=140,["parameters"]={"self","spell","now"},["returns"]={{["description"]="True when ready by the end of the global cooldown; false when its own cooldown prevents recommendation; nil when the client cannot supply a readable result.",["type"]="boolean | nil"},{["description"]="Availability or validation reason when the result is nil.",["type"]="string | nil"}}},["copy"]={["bindings"]={["platform"]="builtin:Platform/spells.lua:platform"},["code"]="\010    if not platform:CanReadValue(record) then return nil, \"restricted-value\" end\010    if type(record) ~= \"table\" then return nil, \"invalid-api-result\" end\010    local result = {}\010    for key, kind in pairs(fields) do\010        local value = record[key]\010        if not platform:CanReadValue(value) then return nil, \"restricted-value\" end\010        if value ~= nil then\010            if type(value) ~= kind and not (kind == \"icon\" and (type(value) == \"number\" or type(value) == \"string\")) then\010                return nil, \"invalid-api-result\"\010            end\010            if type(value) == \"number\" and (value ~= value or value == math.huge or value == -math.huge) then\010                return nil, \"invalid-api-result\"\010            end\010            result[key] = value\010        end\010    end\010    return result\010",["kind"]="function",["line"]=11,["parameters"]={"record","fields"}},["identifier"]={["bindings"]={["platform"]="builtin:Platform/spells.lua:platform"},["code"]="\010    if not platform:CanReadValue(value) then return false, \"restricted-value\" end\010    if type(value) == \"number\" and value > 0 and value < math.huge and value % 1 == 0 then return true end\010    if not idOnly and type(value) == \"string\" and #value > 0 then return true end\010    return false, \"invalid-spell\"\010",["kind"]="function",["line"]=4,["parameters"]={"value","idOnly"}},["platform"]={["kind"]="value"}},["hash"]="12ec8c8ba7c55186f1956a6dc2bae3d48f93f4aadb7b2be7cd4fe2d23741fc23"},["UI/checkbox.lua"]={["bindings"]={["AceGUI"]={["kind"]="value"},["CreateConditionCheckBox"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["AceGUI"]="builtin:UI/checkbox.lua:AceGUI"},["callName"]="addon:CreateConditionCheckBox",["code"]="\010    local widget=AceGUI:Create('RM-CheckBox')\010    ---@cast widget RMConditionCheckBox\010    return widget\010",["description"]="Create a native boolean condition control. Configure SetLabel, SetValue, SetDisabled and OnValueChanged; add it with parent:AddChild(widget).",["kind"]="function",["line"]=30,["parameters"]={"self"},["returns"]={{["description"]="Checkbox widget with boolean value and callback methods.",["type"]="RMConditionCheckBox"}}}},["hash"]="3bff7eef23a477a5166f84968a7b54e13ce67402672f63951c73296c3ee51def"},["UI/condition_inputs.lua"]={["bindings"]={["AceGUI"]={["kind"]="value"},["CreateConditionEditBox"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["AceGUI"]="builtin:UI/condition_inputs.lua:AceGUI"},["callName"]="addon:CreateConditionEditBox",["code"]="\010    local w=AceGUI:Create('RM-ConditionEditBox')\010    ---@cast w RMConditionInput\010    return w\010",["description"]="Create a native text input using the condition widget contract. SetLabel, SetText, SetDisabled and SetCallback configure it; OnEnterPressed commits text. Add it to the callback parent with parent:AddChild(widget).",["kind"]="function",["line"]=128,["parameters"]={"self"},["returns"]={{["description"]="Text widget supporting label, text, pending-edit and callback methods.",["type"]="RMConditionInput"}}},["CreateConditionSlider"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["AceGUI"]="builtin:UI/condition_inputs.lua:AceGUI"},["callName"]="addon:CreateConditionSlider",["code"]="\010    local w=AceGUI:Create('RM-ConditionSlider')\010    ---@cast w RMConditionInput\010    return w\010",["description"]="Create a native numeric condition input with a slider and typed numeric field. Configure SetSliderValues, SetValue, SetIsPercent and SetCallback; OnValueChanged reports committed values. Add it with parent:AddChild(widget).",["kind"]="function",["line"]=134,["parameters"]={"self"},["returns"]={{["description"]="Numeric widget supporting slider bounds, percent display and pending-edit validation.",["type"]="RMConditionInput"}}}},["hash"]="31672a531fffdbb10d3ddced48cafd71592aabfd8f0d77ab23f596226634d8a9"},["UI/condition_layout.lua"]={["bindings"]={["AceGUI"]={["kind"]="value"},["CreateConditionGroup"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["AceGUI"]="builtin:UI/condition_layout.lua:AceGUI"},["callName"]="addon:CreateConditionGroup",["code"]="\010    local group=AceGUI:Create('RM-ConditionGroup')\010    ---@cast group RMConditionGroup\010    return group\010",["description"]="Create a condition field container with RM-owned List, numeric Table and responsive spell-field layouts. It accepts existing condition widgets and legacy custom child widgets; add children with AddChild and attach the group to the callback parent.",["kind"]="function",["line"]=91,["parameters"]={"self"},["returns"]={{["description"]="Condition container supporting SetLayout, AddChild, SetUserData, SetWidth and DoLayout.",["type"]="RMConditionGroup"}}}},["hash"]="96365a5080bdc9bd056baa22085b33b7906fbb9ccad903f96588ba905918b39d"},["UI/selector.lua"]={["bindings"]={["AceGUI"]={["kind"]="value"},["CreateConditionDropdown"]={["args"]={{["description"]="Rotation Master addon instance (implicit with colon calls).",["name"]="self",["type"]="RMAddon"}},["bindings"]={["AceGUI"]="builtin:UI/selector.lua:AceGUI"},["callName"]="addon:CreateConditionDropdown",["code"]="\010    local w=AceGUI:Create('RM-Selector')\010    ---@cast w RMConditionSelector\010    return w\010",["description"]="Create a native condition selector. SetList accepts key-to-label or key-to-entry maps; SetValue selects a key and OnValueChanged reports changes. Add it with parent:AddChild(widget).",["kind"]="function",["line"]=100,["parameters"]={"self"},["returns"]={{["description"]="Selector widget supporting SetList, SetValue, SetLabel, SetDisabled and callbacks.",["type"]="RMConditionSelector"}}}},["hash"]="c5a49590d188aa5f98c077957a25b402d09404ce69da11b0e84c798abee31cf0"},["utils.lua"]={["bindings"]={["_G"]={["kind"]="value"},["cacheHits"]={["kind"]="value"},["cacheMisses"]={["kind"]="value"},["cachedResult"]={["kind"]="value"},["color"]={["kind"]="value"},["compare"]={["args"]={{["description"]="RM operator identifier.",["name"]="operator",["type"]="string"},{["description"]="Left operand; use numbers for ordering and divisibility.",["name"]="left",["type"]="any"},{["description"]="Right operand; DIVISIBLE requires a nonzero divisor.",["name"]="right",["type"]="any"}},["bindings"]={},["callName"]="addon.compare",["code"]="\010    if operator == \"LESSTHAN\" then\010        return left < right\010    elseif operator == \"LESSTHANOREQUALS\" then\010        return left <= right\010    elseif operator == \"GREATERTHAN\" then\010        return left > right\010    elseif operator == \"GREATERTHANOREQUALS\" then\010        return left >= right\010    elseif operator == \"EQUALS\" then\010        return left == right\010    elseif operator == \"NOTEQUALS\" then\010        return left ~= right\010    elseif operator == \"DIVISIBLE\" then\010        return (left % right) == 0\010    else\010        addon:warn(\"Invalid Operator %s\", operator)\010    end\010",["description"]="Compare two values using an RM operator identifier: LESSTHAN, LESSTHANOREQUALS, GREATERTHAN, GREATERTHANOREQUALS, EQUALS, NOTEQUALS or DIVISIBLE. Invalid operators warn and return nil; operands must support the selected Lua operation.",["kind"]="function",["line"]=45,["parameters"]={"operator","left","right"},["returns"]={{["description"]="Comparison result, or nil for an unknown operator.",["type"]="boolean | nil"}}},["getCached"]={["args"]={{["description"]="Evaluation cache, or nil to bypass caching.",["name"]="cache",["type"]="table | nil"},{["description"]="Function or global function name to call.",["name"]="func",["type"]="function | string"},{["description"]="Arguments forwarded unchanged; types, identity, arity and nil positions distinguish cache entries.",["name"]="...",["type"]="any"}},["bindings"]={["getCachedInternal"]="builtin:utils.lua:getCachedInternal"},["callName"]="addon.getCached",["code"]="\010    return getCachedInternal(cache, true, func, ...)\010",["description"]="Call an observation once per cache and exact argument tuple, including nil results. Pass the evaluation cache to share observations within a recommendation cycle; nil cache calls directly.",["kind"]="function",["line"]=317,["parameters"]={"cache","func","..."},["returns"]={{["description"]="All original results, preserving nil positions and return count.",["type"]="..."}}},["getCachedInternal"]={["bindings"]={["_G"]="builtin:utils.lua:_G",["cacheHits"]="builtin:utils.lua:cacheHits",["cacheMisses"]="builtin:utils.lua:cacheMisses",["cachedResult"]="builtin:utils.lua:cachedResult",["nilArgument"]="builtin:utils.lua:nilArgument",["packResults"]="builtin:utils.lua:packResults"},["code"]="\010    if type(func) == 'string' then func = _G[func] end\010    if type(func) ~= 'function' then return end\010    if cache == nil then return func(...) end\010\010    -- Exact keys preserve argument types, identity and arity. Hashing concatenated\010    -- strings allowed unrelated observations to collide, even for numeric IDs.\010    local args, count = { ... }, select('#', ...)\010    for i = 1, count do\010        local value = args[i]\010        if addon.Platform and addon.Platform.CanReadValue and not addon.Platform:CanReadValue(value) then\010            return func(...)\010        end\010        if type(value) == 'number' and value ~= value then return func(...) end\010        if value == nil then args[i] = nilArgument end\010    end\010    local node = cache[func]\010    for i = 1, count do\010        if not node then break end\010        node = node[args[i]]\010    end\010    local result = node and node[cachedResult]\010    if result then\010        cacheHits = cacheHits + 1\010        return unpack(result, 1, result.n)\010    end\010\010    cacheMisses = cacheMisses + 1\010    result = packResults(func(...))\010    local store = recordnil\010    if not store then\010        -- Inspect the packed keys, not potentially restricted return values.\010        for key in pairs(result) do\010            if type(key) == 'number' then store = true; break end\010        end\010    end\010    if store then\010        -- Retry misses and thrown calls must not accumulate empty paths.\010        if not cache[func] then cache[func] = {} end\010        node = cache[func]\010        for i = 1, count do\010            local key = args[i]\010            if not node[key] then node[key] = {} end\010            node = node[key]\010        end\010        node[cachedResult] = result\010    end\010    return unpack(result, 1, result.n)\010",["kind"]="function",["line"]=267,["parameters"]={"cache","recordnil","func","..."}},["getRetryCached"]={["args"]={{["description"]="Evaluation cache, or nil to bypass caching.",["name"]="cache",["type"]="table | nil"},{["description"]="Function or global function name to call.",["name"]="func",["type"]="function | string"},{["description"]="Arguments forwarded unchanged to the observed function.",["name"]="...",["type"]="any"}},["bindings"]={["getCachedInternal"]="builtin:utils.lua:getCachedInternal"},["callName"]="addon.getRetryCached",["code"]="\010    return getCachedInternal(cache, false, func, ...)\010",["description"]="Cache an observation after it returns a non-nil value; retry observations whose entire return tuple is nil. Uses the same exact argument keys as getCached.",["kind"]="function",["line"]=321,["parameters"]={"cache","func","..."},["returns"]={{["description"]="All original results, preserving nil positions and return count.",["type"]="..."}}},["isin"]={["args"]={{["description"]="Table to inspect.",["name"]="array",["type"]="table"},{["description"]="Lookup key.",["name"]="value",["type"]="any"}},["bindings"]={},["callName"]="addon.isin",["code"]="\010    return array[value] ~= nil\010",["description"]="Check whether a table has a non-nil value at a key. A stored false value still counts as present; this does not scan table values.",["kind"]="function",["line"]=153,["parameters"]={"array","value"},["returns"]={{["description"]="True when array[value] is non-nil.",["type"]="boolean"}}},["nilArgument"]={["kind"]="value"},["nullable"]={["args"]={{["description"]="Value to display; false is preserved.",["name"]="value",["type"]="any"},{["description"]="Missing-value display text; omitted uses the localized value placeholder.",["name"]="default",["type"]="string | nil"}},["bindings"]={["color"]="builtin:utils.lua:color"},["callName"]="addon.nullable",["code"]="\010    if value == nil then\010        if default ~= nil then\010            return color.RED .. default .. color.RESET\010        else\010            return color.RED .. L[\"<value>\"] .. color.RESET\010        end\010    end\010    return value\010",["description"]="Return a present value unchanged, or a red display placeholder for nil. Use for readable condition labels, not as a boolean fallback.",["kind"]="function",["line"]=65,["parameters"]={"value","default"},["returns"]={{["description"]="Original non-nil value, or a colored placeholder string.",["type"]="any"}}},["nullable_value"]={["args"]={{["description"]="Key to look up.",["name"]="value",["type"]="any"},{["description"]="Display lookup table.",["name"]="array",["type"]="table | nil"},{["description"]="Missing-value display text; omitted uses the localized value placeholder.",["name"]="default",["type"]="string | nil"}},["bindings"]={["color"]="builtin:utils.lua:color"},["callName"]="addon.nullable_value",["code"]="\010    if value == nil or array == nil or type(array) ~= \"table\" then\010        if default ~= nil then\010            return color.RED .. default .. color.RESET\010        else\010            return color.RED .. L[\"<value>\"] .. color.RESET\010        end\010    end\010    return addon.nullable(array[value], default)\010",["description"]="Look up a table key for display, preserving non-nil results; invalid tables, missing keys and nil keys use nullable placeholder text.",["kind"]="function",["line"]=76,["parameters"]={"value","array","default"},["returns"]={{["description"]="Original non-nil lookup result, or a colored placeholder string.",["type"]="any"}}},["packResults"]={["bindings"]={},["code"]="\010    return { n = select('#', ...), ... }\010",["kind"]="function",["line"]=263,["parameters"]={"..."}},["split"]={["args"]={{["description"]="Text to split.",["name"]="inputstr",["type"]="string"},{["description"]="Lua pattern character-class separator, default %s for whitespace.",["name"]="sep",["type"]="string | nil"}},["bindings"]={["string"]="builtin:utils.lua:string"},["callName"]="addon.split",["code"]="\010    if sep == nil then\010        sep = \"%s\"\010    end\010    local t={}\010    for str in string.gmatch(inputstr, \"([^\"..sep..\"]+)\") do\010        table.insert(t, str)\010    end\010    return t\010",["description"]="Split a string into nonempty runs between separator characters. The separator is inserted into a Lua pattern character class; it is not a literal multi-character delimiter. Empty fields are omitted.",["kind"]="function",["line"]=443,["parameters"]={"inputstr","sep"},["returns"]={{["description"]="Dense array of nonempty text fields.",["type"]="string[]"}}},["string"]={["kind"]="value"},["trim"]={["args"]={{["description"]="Text to trim.",["name"]="s",["type"]="string"}},["bindings"]={},["callName"]="addon.trim",["code"]="\010    return (s:gsub(\"^%s*(.-)%s*$\", \"%1\"))\010",["description"]="Remove leading and trailing Lua-pattern whitespace from a string.",["kind"]="function",["line"]=468,["parameters"]={"s"},["returns"]={{["description"]="Trimmed text.",["type"]="string"}}},["wrap"]={["args"]={{["description"]="Text to wrap.",["name"]="str",["type"]="string"},{["description"]="Target line width, default 72 characters.",["name"]="limit",["type"]="number | nil"}},["bindings"]={},["callName"]="addon.wrap",["code"]="\010    limit = limit or 72\010    local here = 1\010\010    -- the \"\".. is there because :gsub returns multiple values\010    return \"\"..str:gsub(\"(%s+)()(%S+)()\",\010            function(_, st, word, fi)\010                if fi-here > limit then\010                    here = st\010                    return \"\\n\"..word\010                end\010            end)\010",["description"]="Wrap text at whitespace boundaries near a target column count. Long words are retained intact.",["kind"]="function",["line"]=454,["parameters"]={"str","limit"},["returns"]={{["description"]="Text with line breaks inserted at word boundaries.",["type"]="string"}}}},["hash"]="9a8de4fae28a1770b80f3898fecc1206e8d918d8f933d5b36b817f9a7cef7eeb"}}}
